def S(*ids): return ''.join(s(i) for i in ids)
out=[]
for c in A:
    a,b=c['avant'],c['apres']
    if a.startswith("Il est interdit si la fréquence cardiaque"):
        b=("Il est interdit en cas d'hypersensibilité connue au métoprolol ou à d'autres bêtabloquants, de bloc auriculo-ventriculaire de degré 2 et 3, d'insuffisance cardiaque décompensée, de bradycardie sinusale cliniquement patente et de choc cardiogénique"+S('aips-56191-6')+". Il l'est aussi en cas de syndrome du nœud sinusal sans stimulateur permanent, d'asthme ou d'antécédent de bronchospasme, de troubles vasculaires artériels périphériques sévères et de traitement par des inotropes positifs agonistes bêta"+S('aips-56191-6')+". En cas d'infarctus aigu suspecté, il est interdit si la fréquence est inférieure à 45 par minute, si PQ dépasse 0,24 s, si la systolique est inférieure à 100 mmHg ou en insuffisance cardiaque sévère"+S('aips-56191-7')+". Par ailleurs, les patients sous bêtabloquant ne doivent pas recevoir de vérapamil par voie intraveineuse"+S('aips-56191-9','aips-56191-13')+".")
    elif a.startswith("La monographie suisse de l'acide acétylsalicylique"):
        b=("L'information professionnelle d'Aspirine® Cardio (n° Swissmedic 51795) prévoit, dans l'infarctus aigu, 200 à 300 mg d'acide acétylsalicylique par voie intraveineuse ou par voie orale"+S('aips-51795-4','aips-51795-38')+". La voie orale exige une préparation à résorption rapide non gastro-résistante"+S('aips-51795-4')+". En effet, les comprimés gastro-résistants d'Aspirine® Cardio ne doivent être ni écrasés, ni coupés, ni croqués"+S('aips-51795-3')+". À partir du deuxième jour, la dose est de 100 mg d'Aspirine® Cardio par jour"+S('aips-51795-4')+". Elle ne doit pas être utilisée avant 18 ans, faute de données d'efficacité et de sécurité"+S('aips-51795-4')+".</div>"
           '<div class="p">Les contre-indications d\'Aspirine® Cardio comprennent l\'hypersensibilité aux salicylates ou à d\'autres anti-inflammatoires, les antécédents de bronchospasme, d\'urticaire ou de symptômes allergiques après un anti-inflammatoire non stéroïdien, la diathèse hémorragique, les ulcères gastriques ou duodénaux actifs et les hémorragies gastro-intestinales'+S('aips-51795-5')+". Elles comprennent aussi les maladies inflammatoires de l'intestin, les troubles sévères de la fonction hépatique (cirrhose et ascite), l'insuffisance rénale sévère avec une clairance inférieure à 30 ml/min et l'insuffisance cardiaque sévère NYHA III-IV"+S('aips-51795-5')+". S'y ajoutent l'association au méthotrexate à 15 mg par semaine ou plus, le troisième trimestre de la grossesse et la douleur postopératoire après pontage coronarien"+S('aips-51795-5')+".</div>"
           '<div class="p">L\'acide acétylsalicylique Panpharma Inj (n° Swissmedic 47256) est indiqué dans la douleur aiguë d\'intensité modérée à sévère lorsque la voie orale est impossible'+S('aips-47256-1','aips-47256-39')+". La dose adulte est de 500 mg par injection 3 fois par jour, au maximum 3 g par jour, et on ne l'administre pas à l'enfant de moins de 12 ans"+S('aips-47256-3')+". Sa notice ne cite pas l'infarctus ; la charge intraveineuse dans l'infarctus repose donc sur l'information professionnelle d'Aspirine® Cardio"+S('aips-47256-1','aips-51795-4')+". Ses contre-indications comprennent l'hypersensibilité aux salicylates, aux anti-inflammatoires ou aux excipients, la mastocytose, l'asthme provoqué par les salicylates ou les anti-inflammatoires et l'ulcère gastro-duodénal en évolution"+S('aips-47256-5')+". Elles comprennent aussi l'hémorragie digestive, toute maladie hémorragique, l'insuffisance hépatique sévère, l'insuffisance rénale sévère (clairance inférieure à 30 ml/min) et l'insuffisance cardiaque sévère (NYHA III-V)"+S('aips-47256-5')+".")
    elif a.startswith("Aucune monographie AIPS lisible d'atorvastatine"):
        b=("L'information professionnelle de Sortis® (atorvastatine, n° Swissmedic 54085) prévoit une dose initiale usuelle de 10 mg une fois par jour"+S('aips-54085-4','aips-54085-84')+". La dose journalière maximale est de 80 mg en une prise"+S('aips-54085-4')+". Les contre-indications comprennent l'hypersensibilité, une pathologie active du foie ou une élévation durable inexpliquée des transaminases à plus du triple de la normale, la cholestase et la myopathie"+S('aips-54085-8')+". Elles comprennent aussi la grossesse, l'allaitement et l'association au glécaprévir et au pibrentasvir"+S('aips-54085-9','aips-54085-44')+".")
